inline std::string tr(const std::string& s) {
    if (s.empty()) return s;
    for (auto& p : exact()) if (p.first == s) return p.second;
    // «Action» names inside status messages
    std::string o = s;
    for (auto& p : exact()) {
        std::string q = "«" + p.first + "»";
        for (size_t at; (at = o.find(q)) != std::string::npos;) o.replace(at, q.size(), "\"" + p.second + "\"");
    }
    static std::vector<std::pair<std::string, std::string>> fr;
    if (fr.empty()) { fr = fragments(); std::stable_sort(fr.begin(), fr.end(), [](auto& a, auto& b) { return a.first.size() > b.first.size(); }); }
    for (auto& p : fr) for (size_t at = 0; (at = o.find(p.first, at)) != std::string::npos; at += p.second.size()) o.replace(at, p.first.size(), p.second);
    return o;
}

